import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { catchError, firstValueFrom, of } from 'rxjs';

/** the REAL drawing of one function icon: the first `<symbol id>` the templates ship (generated by tools/icon-real-library.cjs, cross-checked against the BE allow-list by sha256) */
export interface RealIcon { vb: string | null; paint: Record<string, string>; inner: string; sha256: string; defs: number; variants: number; files: string[] }
export type RealIconsPhase = 'idle' | 'loading' | 'ready' | 'error';

/** the icon library draws THESE (not a separate sample set); a load failure is an explicit error state, the icons already loaded stay */
@Injectable({ providedIn: 'root' })
export class RealIconsService {
	private readonly http = inject(HttpClient);
	readonly phase = signal<RealIconsPhase>('idle');
	readonly icons = signal<Record<string, RealIcon>>({});
	private inflight: Promise<void> | null = null;

	load(force = false): Promise<void> {
		if (this.inflight) return this.inflight;
		if (!force && this.phase() === 'ready') return Promise.resolve();
		this.inflight = (async () => {
			if (this.phase() !== 'ready') this.phase.set('loading');
			const d = await firstValueFrom(this.http.get<{ icons: Record<string, RealIcon> }>('/assets/site-control/real-icons.json').pipe(catchError(() => of(null))));
			if (!d || !d.icons || typeof d.icons !== 'object' || !Object.keys(d.icons).length) { if (this.phase() !== 'ready') this.phase.set('error'); return; }
			this.icons.set(d.icons); this.phase.set('ready');
		})().finally(() => { this.inflight = null; });
		return this.inflight;
	}
	get(id: string): RealIcon | null { return this.icons()[id] ?? null; }
	/** the whole `<svg>` text of the real drawing with the symbol's own paint attributes (what `<use>` would draw) */
	fullSvg(id: string): string | null {
		const r = this.get(id); if (!r) return null;
		const a = Object.entries(r.paint).filter(([k]) => k !== 'preserveAspectRatio').map(([k, v]) => ` ${k}="${v.replace(/"/g, '&quot;')}"`).join('');
		return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${r.vb ?? '0 0 24 24'}"${a}>${r.inner}</svg>`;
	}
}
